-- 031_staging_pks.sql — DB1: bổ sung khoá chính cho 2 bảng staging chưa có PK.
--
-- staging.wn_example / staging.wn_relation là dump thô WordNet, không có khoá tự
-- nhiên ổn định. Thêm cột `id` identity (surrogate) làm PK để mọi bảng staging
-- đều định danh được khi cần đối soát/rollback; `GENERATED BY DEFAULT` nên COPY
-- cũ (không liệt kê cột id) vẫn chạy nguyên trạng.

ALTER TABLE staging.wn_example
  ADD COLUMN id bigint GENERATED BY DEFAULT AS IDENTITY;
ALTER TABLE staging.wn_example
  ADD CONSTRAINT wn_example_pkey PRIMARY KEY (id);
COMMENT ON COLUMN staging.wn_example.id IS
  'Surrogate PK (DB1) — WordNet không có khoá tự nhiên.';

ALTER TABLE staging.wn_relation
  ADD COLUMN id bigint GENERATED BY DEFAULT AS IDENTITY;
ALTER TABLE staging.wn_relation
  ADD CONSTRAINT wn_relation_pkey PRIMARY KEY (id);
COMMENT ON COLUMN staging.wn_relation.id IS
  'Surrogate PK (DB1) — WordNet không có khoá tự nhiên.';
